contract InvMutTest {
    C c;
    uint public cnt;
    address lastFrom;
    address lastTo;
    uint lastV;
    constructor(C _c) { c = _c; }
    function run(address from, uint n, uint v) public {
        require(n > 0 && n <= 5);
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(uint160(1000 + i));
        }
        cnt = 0;
        lastFrom = address(0);
        lastTo = address(0);
        lastV = 0;
        bool reverted = false;
        bool ok = false;
        try c.transfer(from, address(this), tos, v) returns (bool r) { ok = r; } catch { reverted = true; }
        assert(reverted || (ok && cnt == n && lastFrom == from && lastTo == tos[n-1] && lastV == v));
    }
    fallback() external payable {
        if (msg.data.length >= 4 && bytes4(msg.data) == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
            (address f, address t, uint256 vv) = abi.decode(msg.data[4:], (address, address, uint256));
            cnt++;
            lastFrom = f;
            lastTo = t;
            lastV = vv;
        }
    }
    receive() external payable {}
}

