contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address token, address[] memory tos, uint v) public {
        // Rule 1: empty list must revert.
        bool emptyReverted;
        try c.transfer(from, token, new address[](0), v) {
            emptyReverted = false;
        } catch {
            emptyReverted = true;
        }
        assert(emptyReverted);

        // Rule 2: if the batch call succeeds, it returns true; otherwise it reverts.
        bool reverted;
        bool ok;
        try c.transfer(from, token, tos, v) returns (bool r) {
            reverted = false;
            ok = r;
        } catch {
            reverted = true;
        }
        assert(reverted || ok);
    }
}

